void PEGTransformerFactory::InitializeNestedColumnNameTrampoline(PEGTransformer &transformer,
                                                                 GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	auto &repeat_opt = list_pr.GetChild(0).Cast<OptionalParseResult>();
	idx_t dynamic_child_count = 0;
	if (repeat_opt.HasResult()) {
		auto &repeat_pr = repeat_opt.GetResult().Cast<RepeatParseResult>();
		auto repeat_children = repeat_pr.GetChildren();
		dynamic_child_count = repeat_children.size();
		process.ReserveChildSlots(1 + dynamic_child_count - 1);
		for (idx_t i = repeat_children.size(); i > 0; i--) {
			auto child_idx = i - 1;
			process.PushChild({transformer.GetRule(PEGRuleId::IdentifierDot), repeat_children[child_idx].get()},
			                  0 + child_idx);
		}
	} else {
		process.ReserveChildSlots(1 - 1);
	}
}

arena_ptr<TransformResultValue>
PEGTransformerFactory::FinalizeNestedColumnNameTrampoline(PEGTransformer &transformer,
                                                          GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	idx_t dynamic_child_count = 0;
	auto &dynamic_repeat_opt = list_pr.GetChild(0).Cast<OptionalParseResult>();
	if (dynamic_repeat_opt.HasResult()) {
		auto &dynamic_repeat_pr = dynamic_repeat_opt.GetResult().Cast<RepeatParseResult>();
		auto dynamic_repeat_children = dynamic_repeat_pr.GetChildren();
		dynamic_child_count = dynamic_repeat_children.size();
	}
	optional<vector<Identifier>> identifier_dot {};
	if (dynamic_child_count > 0) {
		vector<Identifier> identifier_dot_value;
		identifier_dot_value.reserve(dynamic_child_count);
		for (idx_t i = 0; i < 0 + dynamic_child_count; i++) {
			identifier_dot_value.push_back(process.TakeResult<Identifier>(i));
		}
		identifier_dot = std::move(identifier_dot_value);
	}
	auto column_name = list_pr.GetChild(1).Cast<IdentifierParseResult>().identifier;
	auto result = TransformNestedColumnName(transformer, identifier_dot, column_name);
	return transformer.MakeResult<unique_ptr<ColumnRefExpression>>(std::move(result));
}

