void PEGTransformerFactory::InitializeExplainOptionListTrampoline(PEGTransformer &transformer,
                                                                  GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	auto list_items = ExtractParseResultsFromList(ExtractResultFromParens(list_pr.GetChild(0)));
	auto dynamic_child_count = list_items.size();
	process.ReserveChildSlots(1 + dynamic_child_count - 1);
	for (idx_t i = list_items.size(); i > 0; i--) {
		auto child_idx = i - 1;
		process.PushChild({transformer.GetRule(PEGRuleId::ExplainOption), list_items[child_idx].get()}, 0 + child_idx);
	}
}

