void PEGTransformerFactory::InitializeNotMatchedClauseTrampoline(PEGTransformer &transformer,
                                                                 GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	process.ReserveChildSlots(3);
	process.PushChild({transformer.GetRule(PEGRuleId::MatchedClauseAction), list_pr.GetChild(6)}, 2);
	auto &and_expression_opt = list_pr.GetChild(4).Cast<OptionalParseResult>();
	if (and_expression_opt.HasResult()) {
		process.PushChild({transformer.GetRule(PEGRuleId::AndExpression), and_expression_opt.GetResult()}, 1);
	}
	auto &by_source_or_target_opt = list_pr.GetChild(3).Cast<OptionalParseResult>();
	if (by_source_or_target_opt.HasResult()) {
		process.PushChild({transformer.GetRule(PEGRuleId::BySourceOrTarget), by_source_or_target_opt.GetResult()}, 0);
	}
}

arena_ptr<TransformResultValue>
PEGTransformerFactory::FinalizeNotMatchedClauseTrampoline(PEGTransformer &transformer,
                                                          GeneratedTransformProcess &process) {
	optional<MergeActionCondition> by_source_or_target {};
	if (process.child_results[0]) {
		by_source_or_target = process.TakeResult<MergeActionCondition>(0);
	}
	optional<unique_ptr<ParsedExpression>> and_expression {};
	if (process.child_results[1]) {
		and_expression = process.TakeResult<unique_ptr<ParsedExpression>>(1);
	}
	auto matched_clause_action = process.TakeResult<unique_ptr<MergeIntoAction>>(2);
	auto result = TransformNotMatchedClause(transformer, by_source_or_target, std::move(and_expression),
	                                        std::move(matched_clause_action));
	return transformer.MakeResult<pair<MergeActionCondition, unique_ptr<MergeIntoAction>>>(std::move(result));
}

