void PEGTransformerFactory::InitializeWithStatementTrampoline(PEGTransformer &transformer,
                                                              GeneratedTransformProcess &process) {
	auto &list_pr = process.parse_result.Cast<ListParseResult>();
	process.ReserveChildSlots(5);
	process.PushChild({transformer.GetRule(PEGRuleId::CTEBody), list_pr.GetChild(5)}, 4);
	auto &materialized_opt = list_pr.GetChild(4).Cast<OptionalParseResult>();
	if (materialized_opt.HasResult()) {
		process.PushChild({transformer.GetRule(PEGRuleId::Materialized), materialized_opt.GetResult()}, 3);
	}
	auto &using_key_opt = list_pr.GetChild(2).Cast<OptionalParseResult>();
	if (using_key_opt.HasResult()) {
		process.PushChild({transformer.GetRule(PEGRuleId::UsingKey), using_key_opt.GetResult()}, 2);
	}
	auto &column_aliases_opt = list_pr.GetChild(1).Cast<OptionalParseResult>();
	if (column_aliases_opt.HasResult()) {
		process.PushChild({transformer.GetRule(PEGRuleId::ColumnAliases), column_aliases_opt.GetResult()}, 1);
	}
	process.PushChild({transformer.GetRule(PEGRuleId::ColIdOrString), list_pr.GetChild(0)}, 0);
}

arena_ptr<TransformResultValue>
PEGTransformerFactory::FinalizeWithStatementTrampoline(PEGTransformer &transformer,
                                                       GeneratedTransformProcess &process) {
	auto col_id_or_string = process.TakeResult<Identifier>(0);
	optional<vector<string>> column_aliases {};
	if (process.child_results[1]) {
		column_aliases = process.TakeResult<vector<string>>(1);
	}
	optional<vector<unique_ptr<ParsedExpression>>> using_key {};
	if (process.child_results[2]) {
		using_key = process.TakeResult<vector<unique_ptr<ParsedExpression>>>(2);
	}
	optional<bool> materialized {};
	if (process.child_results[3]) {
		materialized = process.TakeResult<bool>(3);
	}
	auto cte_body = process.TakeResult<unique_ptr<TableRef>>(4);
	auto result = TransformWithStatement(transformer, col_id_or_string, column_aliases, std::move(using_key),
	                                     materialized, std::move(cte_body));
	return transformer.MakeResult<pair<Identifier, unique_ptr<CommonTableExpressionInfo>>>(std::move(result));
}

